using Microsoft.EntityFrameworkCore;
using Sace.Api.Contracts;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;
using Sace.Api.Services;

namespace Sace.Api;

public static class LegalV2Endpoints {
  public static RouteGroupBuilder MapLegalV2Endpoints(this RouteGroupBuilder api){
    api.MapPost("/operations/{id:guid}/legal/evaluate",async(Guid id,HttpContext ctx,ILegalAuditEngineV2 engine,CancellationToken ct)=>Results.Ok(await engine.ExecuteAsync(id,ctx.User.UserId(),ct)));
    api.MapGet("/operations/{id:guid}/legal",async(Guid id,SaceDbContext db,CancellationToken ct)=>{var audit=await LegalAudits(db,id).FirstOrDefaultAsync(ct);return audit is null?Results.NoContent():Results.Ok(audit);});
    api.MapGet("/operations/{id:guid}/legal/history",async(Guid id,int page,int pageSize,SaceDbContext db,CancellationToken ct)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=LegalAudits(db,id);var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct),page,pageSize,total,pages=(int)Math.Ceiling(total/(double)pageSize)});});
    api.MapGet("/operations/{operationId:guid}/legal/{resultId:guid}",async(Guid operationId,Guid resultId,SaceDbContext db,CancellationToken ct)=>{var result=await db.AuditResults.AsNoTracking().AsSplitQuery().Include(x=>x.NormativeRule).Include(x=>x.SourceVersion).ThenInclude(x=>x!.OfficialLegalSource).Include(x=>x.LegalEvidence).Include(x=>x.LegalReviews).ThenInclude(x=>x.ReviewerUser).FirstOrDefaultAsync(x=>x.Id==resultId&&x.Audit.TradeOperationId==operationId,ct);return result is null?Results.NotFound():Results.Ok(result);});
    api.MapPost("/legal/results/{id:guid}/review",async(Guid id,LegalReviewRequest request,HttpContext ctx,ILegalReviewService service,CancellationToken ct)=>Results.Ok(await service.ReviewAsync(id,ctx.User.UserId(),request.Decision,request.ReviewedOutcome,request.Reason,ct)));

    api.MapGet("/legal/findings",async(string? outcome,FindingStatus? status,string? rule,DateTime? from,DateTime? to,Guid? operationId,Severity? severity,bool? reviewed,int page,int pageSize,SaceDbContext db,CancellationToken ct)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Findings.AsNoTracking().Where(x=>x.OriginalAuditResultId!=null).AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(rule))q=q.Where(x=>x.RuleId.Contains(rule));if(from.HasValue)q=q.Where(x=>x.CreatedAt>=from.Value);if(to.HasValue)q=q.Where(x=>x.CreatedAt<to.Value.Date.AddDays(1));if(operationId.HasValue)q=q.Where(x=>x.TradeOperationId==operationId);if(severity.HasValue)q=q.Where(x=>x.Severity==severity);if(reviewed.HasValue)q=reviewed.Value?q.Where(x=>x.ConfirmedAt!=null||x.DismissedAt!=null||x.LegalReviews.Any()):q.Where(x=>x.ConfirmedAt==null&&x.DismissedAt==null&&!x.LegalReviews.Any());if(!string.IsNullOrWhiteSpace(outcome)&&Enum.TryParse<LegalOutcome>(outcome,true,out var parsed))q=q.Where(x=>x.OriginalAuditResult!.Outcome==parsed);var total=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.Number,x.TradeOperationId,x.TradeOperation.Folio,x.TradeOperation.PedimentoNumber,x.RuleId,x.Description,x.Severity,x.Status,x.CorrectionStatus,x.CreatedAt,x.ConfirmedAt,x.DismissedAt,outcome=x.OriginalAuditResult!.Outcome,humanReviewed=x.ConfirmedAt!=null||x.DismissedAt!=null||x.LegalReviews.Any()}).ToListAsync(ct);return Results.Ok(new{items,page,pageSize,total,pages=(int)Math.Ceiling(total/(double)pageSize)});});
    api.MapGet("/legal/findings/{id:guid}",async(Guid id,SaceDbContext db,CancellationToken ct)=>{var item=await db.Findings.AsNoTracking().AsSplitQuery().Include(x=>x.TradeOperation).Include(x=>x.DocumentType).Include(x=>x.OriginalAuditResult).ThenInclude(x=>x!.LegalEvidence).Include(x=>x.OriginalAuditResult).ThenInclude(x=>x!.SourceVersion).ThenInclude(x=>x!.OfficialLegalSource).Include(x=>x.History).Include(x=>x.LegalReviews).ThenInclude(x=>x.ReviewerUser).FirstOrDefaultAsync(x=>x.Id==id&&x.OriginalAuditResultId!=null,ct);return item is null?Results.NotFound():Results.Ok(item);});
    api.MapPost("/legal/findings/{id:guid}/review",async(Guid id,LegalFindingActionRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>await FindingAction(id,request,ctx,db,"review",ct));
    api.MapPost("/legal/findings/{id:guid}/correction",async(Guid id,LegalFindingActionRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>await FindingAction(id,request,ctx,db,"correction",ct));
    api.MapPost("/legal/findings/{id:guid}/close",async(Guid id,LegalFindingActionRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>await FindingAction(id,request,ctx,db,"close",ct));

    api.MapGet("/legal-rules",async(LegalRuleStatus? status,string? search,int page,int pageSize,SaceDbContext db,CancellationToken ct)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.NormativeRules.AsNoTracking().Where(x=>x.IsLegalRule&&x.RuleCategory==RuleCategory.LEGAL);if(status.HasValue)q=q.Where(x=>x.LegalStatus==status);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Code.Contains(search)||x.Name.Contains(search));var total=await q.CountAsync(ct);var items=await q.OrderBy(x=>x.Code).ThenByDescending(x=>x.Version).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.Code,x.Version,title=x.Name,x.LegalStatus,x.EffectiveFrom,x.EffectiveTo,x.AutomationLevel,x.Limitations,citations=x.LegalSourceCitations.Count,conditions=x.LegalConditions.Count,evidence=x.LegalEvidenceRequirements.Count,evaluations=db.AuditResults.Count(r=>r.NormativeRuleId==x.Id)}).ToListAsync(ct);return Results.Ok(new{items,page,pageSize,total,pages=(int)Math.Ceiling(total/(double)pageSize)});});
    api.MapGet("/legal-rules/{id:guid}",async(Guid id,SaceDbContext db,CancellationToken ct)=>{var item=await RuleQuery(db).AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);return item is null?Results.NotFound():Results.Ok(item);});
    api.MapPost("/legal-rules",async(LegalRuleV2Request request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var error=await Validate(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"LEGAL_RULE_INVALID",error,new{}));var code=request.Code.Trim().ToUpperInvariant();var version=(await db.NormativeRules.Where(x=>x.Code==code).MaxAsync(x=>(int?)x.Version,ct)??0)+1;var item=Build(request,code,version);db.NormativeRules.Add(item);Log(db,ctx.User.UserId(),"LEGAL_RULE_VERSION_CREATED",item.Id,$"{code} v{version} DRAFT.");await db.SaveChangesAsync(ct);return Results.Created($"/api/legal-rules/{item.Id}",item);});
    api.MapPut("/legal-rules/{id:guid}",async(Guid id,LegalRuleV2Request request,SaceDbContext db,CancellationToken ct)=>{var item=await RuleQuery(db).FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound();if(item.LegalStatus!=LegalRuleStatus.DRAFT)return Results.BadRequest(new ApiError(400,"VERIFIED_IMMUTABLE","Sólo una regla DRAFT puede editarse; cree una nueva versión.",new{}));var error=await Validate(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"LEGAL_RULE_INVALID",error,new{}));db.LegalRuleConditions.RemoveRange(item.LegalConditions);db.LegalEvidenceRequirements.RemoveRange(item.LegalEvidenceRequirements);db.LegalEvidenceMappings.RemoveRange(item.LegalEvidenceMappings);db.LegalRuleSourceCitations.RemoveRange(item.LegalSourceCitations);Apply(item,request);await db.SaveChangesAsync(ct);return Results.Ok(item);});
    api.MapPost("/legal-rules/{id:guid}/version",async(Guid id,LegalRuleV2Request request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var source=await db.NormativeRules.FindAsync([id],ct);if(source is null)return Results.NotFound();var error=await Validate(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"LEGAL_RULE_INVALID",error,new{}));var version=(await db.NormativeRules.Where(x=>x.Code==source.Code).MaxAsync(x=>(int?)x.Version,ct)??0)+1;var item=Build(request,source.Code,version);db.NormativeRules.Add(item);Log(db,ctx.User.UserId(),"LEGAL_RULE_VERSION_CREATED",item.Id,$"{source.Code} v{version} DRAFT.");await db.SaveChangesAsync(ct);return Results.Created($"/api/legal-rules/{item.Id}",item);});
    api.MapPost("/legal-rules/{id:guid}/verify",async(Guid id,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var item=await RuleQuery(db).FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound();if(item.LegalStatus!=LegalRuleStatus.DRAFT&&item.LegalStatus!=LegalRuleStatus.REVIEW_REQUIRED)return Results.BadRequest(new ApiError(400,"INVALID_RULE_STATUS","La regla no está disponible para verificación.",new{}));var validSources=item.LegalSourceCitations.Count>0&&item.LegalSourceCitations.All(x=>x.OfficialSourceCitation.OfficialLegalSourceVersion.VerificationStatus==SourceVerificationStatus.VERIFIED&&x.OfficialSourceCitation.OfficialLegalSourceVersion.OfficialLegalSource.Status==SourceVerificationStatus.VERIFIED);if(!validSources||item.LegalConditions.Count==0||item.LegalEvidenceRequirements.Count==0||item.EffectiveFrom==default)return Results.BadRequest(new ApiError(400,"LEGAL_RULE_VERIFICATION_FAILED","Se requieren fuente y cita VERIFIED, vigencia, condiciones y evidencia configurada.",new{}));item.LegalStatus=LegalRuleStatus.VERIFIED;item.IsActive=true;Log(db,ctx.User.UserId(),"LEGAL_RULE_VERIFIED",item.Id,$"{item.Code} v{item.Version}.");await db.SaveChangesAsync(ct);return Results.Ok(item);});
    return api;
  }
  static IQueryable<Audit> LegalAudits(SaceDbContext db,Guid id)=>db.Audits.AsNoTracking().AsSplitQuery().Where(x=>x.TradeOperationId==id&&x.AuditType==AuditType.Legal&&x.NormativeVersionLabel!.StartsWith("LEGAL V2")).Include(x=>x.Results).ThenInclude(x=>x.LegalEvidence).Include(x=>x.Results).ThenInclude(x=>x.LegalReviews).OrderByDescending(x=>x.StartedAt);
  static IQueryable<NormativeRule> RuleQuery(SaceDbContext db)=>db.NormativeRules.AsSplitQuery().Include(x=>x.LegalConditions).Include(x=>x.LegalEvidenceRequirements).Include(x=>x.LegalEvidenceMappings).Include(x=>x.LegalSourceCitations).ThenInclude(x=>x.OfficialSourceCitation).ThenInclude(x=>x.OfficialLegalSourceVersion).ThenInclude(x=>x.OfficialLegalSource).Where(x=>x.IsLegalRule&&x.RuleCategory==RuleCategory.LEGAL);
  static async Task<IResult> FindingAction(Guid id,LegalFindingActionRequest request,HttpContext ctx,SaceDbContext db,string action,CancellationToken ct){if(string.IsNullOrWhiteSpace(request.Reason))return Results.BadRequest(new ApiError(400,"REASON_REQUIRED","La razón es obligatoria.",new{}));var item=await db.Findings.FirstOrDefaultAsync(x=>x.Id==id&&x.OriginalAuditResultId!=null,ct);if(item is null)return Results.NotFound();var before=item.Status;var user=ctx.User.UserId();if(action=="review"){item.Status=FindingStatus.CONFIRMED;item.ConfirmedBy=user;item.ConfirmedAt=DateTime.UtcNow;}else if(action=="correction"){item.Status=FindingStatus.CORRECTED;item.CorrectionStatus=LegalCorrectionStatus.CORRECTED;item.CorrectionNotes=request.Notes??request.Reason;}else{if(item.Status is not (FindingStatus.CONFIRMED or FindingStatus.CORRECTED or FindingStatus.DISMISSED))return Results.BadRequest(new ApiError(400,"INVALID_TRANSITION","Confirme, corrija o descarte el hallazgo antes de cerrarlo.",new{}));item.Status=FindingStatus.CLOSED;item.ResolvedAt=DateTime.UtcNow;}item.UpdatedAt=DateTime.UtcNow;db.FindingHistories.Add(new(){FindingId=item.Id,PreviousStatus=before,NewStatus=item.Status,Comment=request.Reason.Trim(),ChangedBy=user});Log(db,user,action=="review"?"LEGAL_FINDING_REVIEWED":action=="correction"?"LEGAL_FINDING_CORRECTED":"LEGAL_FINDING_CLOSED",item.Id,request.Reason.Trim());await db.SaveChangesAsync(ct);return Results.Ok(item);}
  static NormativeRule Build(LegalRuleV2Request request,string code,int version){var x=new NormativeRule{Code=code,Version=version,LegalStatus=LegalRuleStatus.DRAFT};Apply(x,request);return x;}
  static void Apply(NormativeRule x,LegalRuleV2Request r){x.Name=r.Title.Trim();x.Description=r.Description.Trim();x.NormativeSource=r.NormativeSource;x.RuleCategory=RuleCategory.LEGAL;x.IsLegalRule=true;x.IsIncludedInLegalCompliance=r.IsIncludedInLegalCompliance;x.AutomationLevel=r.AutomationLevel;x.EffectiveFrom=r.EffectiveFrom.ToUniversalTime();x.EffectiveTo=r.EffectiveTo?.ToUniversalTime();x.Limitations=r.Limitations?.Trim();x.IsActive=false;x.LegalConditions=r.Conditions.Select(c=>new LegalRuleCondition{GroupCode=c.GroupCode.Trim().ToUpperInvariant(),Sequence=Math.Max(1,c.Sequence),FieldCode=c.FieldCode.Trim().ToUpperInvariant(),Operator=c.Operator,ExpectedValue=c.ExpectedValue?.Trim(),ExpectedValue2=c.ExpectedValue2?.Trim(),ValueType=c.ValueType,Required=c.Required,FailureBehavior=c.FailureBehavior}).ToList();x.LegalEvidenceRequirements=r.EvidenceRequirements.Select(e=>new LegalEvidenceRequirement{Code=e.Code.Trim().ToUpperInvariant(),Name=e.Name.Trim(),EvidenceType=e.EvidenceType,Required=e.Required,AlternativeGroup=e.AlternativeGroup?.Trim(),MinimumConfidence=e.MinimumConfidence,ManualVerificationRequired=e.ManualVerificationRequired,Description=e.Description?.Trim()??"",OfficialSourceCitationId=e.OfficialSourceCitationId}).ToList();x.LegalEvidenceMappings=r.Mappings.Select(m=>new LegalEvidenceMapping{SourceType=m.SourceType,SourceOutcome=m.SourceOutcome?.Trim().ToUpperInvariant(),TargetEvidenceCode=m.TargetEvidenceCode.Trim().ToUpperInvariant(),SourceFieldCode=m.SourceFieldCode?.Trim().ToUpperInvariant()}).ToList();x.LegalSourceCitations=r.SourceCitationIds.Distinct().Select(id=>new LegalRuleSourceCitation{OfficialSourceCitationId=id}).ToList();}
  static async Task<string?> Validate(LegalRuleV2Request r,SaceDbContext db,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Code)||string.IsNullOrWhiteSpace(r.Title)||string.IsNullOrWhiteSpace(r.Description))return "Código, título y descripción son obligatorios.";if(r.EffectiveTo.HasValue&&r.EffectiveTo<r.EffectiveFrom)return "La vigencia final no puede ser anterior a la inicial.";if(r.Conditions.Count==0||r.EvidenceRequirements.Count==0)return "Configure al menos una condición y un requisito de evidencia.";if(r.SourceCitationIds.Count==0)return "Asocie al menos una cita oficial.";if(await db.OfficialSourceCitations.CountAsync(x=>r.SourceCitationIds.Contains(x.Id),ct)!=r.SourceCitationIds.Distinct().Count())return "Una cita oficial no existe.";if(r.Mappings.Any(x=>x.SourceType==(LegalEvidenceType)999))return "Mapping no soportado.";return null;}
  static void Log(SaceDbContext db,Guid user,string action,Guid id,string details)=>db.SystemAuditLogs.Add(new(){UserId=user,Action=action,EntityType="LEGAL",EntityId=id.ToString(),Details=details});
}
